<?php

namespace Tests\Feature\Realtime;

use App\Http\Middleware\HandleInertiaRequests;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Http\Request;
use Inertia\Testing\AssertableInertia as Assert;
use Tests\Support\InteractsWithRealtime;
use Tests\Support\WidgetFixtures;
use Tests\TestCase;

/** The dashboard learns the Reverb address at runtime (the keys are generated by the install, after the bundle was built). */
class SharedRealtimePropTest extends TestCase
{
    use InteractsWithRealtime, RefreshDatabase, WidgetFixtures;

    protected function setUp(): void
    {
        parent::setUp();

        $this->useFortifyMode();
    }

    public function test_active_staff_get_the_public_websocket_address_and_nothing_secret(): void
    {
        $this->useReverbBroadcaster();

        $this->actingAs($this->agent())
            ->get(route('dashboard'))
            ->assertInertia(fn (Assert $page) => $page
                ->where('realtime', [
                    'key' => self::REVERB_KEY,
                    'host' => 'chat.example.test',
                    'port' => 443,
                    'scheme' => 'https',
                ]));
    }

    public function test_it_is_null_when_realtime_is_not_configured(): void
    {
        config(['broadcasting.default' => 'null']);

        $this->actingAs($this->agent())
            ->get(route('dashboard'))
            ->assertInertia(fn (Assert $page) => $page->where('realtime', null));
    }

    public function test_guests_and_staff_who_cannot_chat_never_get_it(): void
    {
        $this->useReverbBroadcaster();

        $this->get(route('login'))
            ->assertInertia(fn (Assert $page) => $page->where('realtime', null));

        foreach ([['is_admin' => false, 'is_agent' => false, 'is_active' => true], ['is_admin' => false, 'is_agent' => true, 'is_active' => false]] as $flags) {
            $request = Request::create('/dashboard');
            $request->setUserResolver(fn (): User => User::factory()->create($flags));

            $this->assertNull(app(HandleInertiaRequests::class)->share($request)['realtime'], json_encode($flags));
        }
    }

    private function agent(): User
    {
        return User::factory()->create(['is_admin' => false, 'is_agent' => true, 'is_active' => true]);
    }
}
